action.command:
node -e "
const { execSync } = require('child_process');
const path = require('path');
const input = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const root = input.workspaceRoot || '.';
const apps = ['frontend-guest', 'frontend-staff'];
let allPassed = true;
const results = [];

for (const app of apps) {
  const dir = path.join(root, app);
  const fs = require('fs');
  if (!fs.existsSync(dir)) continue;

  // 1. Type-check
  try {
    execSync('npx tsc --noEmit', { cwd: dir, stdio: 'pipe' });
    results.push({ app, step: 'tsc', status: 'pass' });
  } catch (e) {
    results.push({ app, step: 'tsc', status: 'fail', detail: (e.stdout || e.stderr || '').toString().slice(0, 500) });
    allPassed = false;
  }

  // 2. Tests (only if vitest config exists)
  const vitestCfg = path.join(dir, 'vitest.config.ts');
  if (fs.existsSync(vitestCfg)) {
    try {
      execSync('npm test -- --run', { cwd: dir, stdio: 'pipe', timeout: 120000 });
      results.push({ app, step: 'tests', status: 'pass' });
    } catch (e) {
      results.push({ app, step: 'tests', status: 'fail', detail: (e.stdout || e.stderr || '').toString().slice(0, 500) });
      allPassed = false;
    }
  } else {
    results.push({ app, step: 'tests', status: 'skipped', detail: 'no vitest.config.ts' });
  }

  // 3. Build
  try {
    execSync('npm run build', { cwd: dir, stdio: 'pipe', timeout: 120000 });
    results.push({ app, step: 'build', status: 'pass' });
  } catch (e) {
    results.push({ app, step: 'build', status: 'fail', detail: (e.stdout || e.stderr || '').toString().slice(0, 500) });
    allPassed = false;
  }
}

const summary = results.map(r => r.app + ':' + r.step + '=' + r.status + (r.detail ? ' >> ' + r.detail : '')).join('\n');
if (allPassed) {
  process.stdout.write('All verification checks passed.\n' + summary + '\n');
  process.exit(0);
} else {
  process.stderr.write('Verification FAILED. Fix errors before marking task complete.\n' + summary + '\n');
  process.exit(2);
}
"
